/**
 * @param {{ id: string, size: number }[]} items
 * @param {number} slotSize
 * @returns {string[][]} the ids of the items in each slot
 */
export function packSlots(items, slotSize) {
	// Placement order: decreasing size, then ascending id (R2).
	const ordered = [...items].sort((x, y) => {
		if (y.size !== x.size) return y.size - x.size;
		if (x.id < y.id) return -1;
		if (x.id > y.id) return 1;
		return 0;
	});

	// Reject any item larger than the slot, naming the first in
	// placement order (R5).
	for (const item of ordered) {
		if (item.size > slotSize) {
			throw new RangeError(
				`item "${item.id}" size ${item.size} exceeds slotSize ${slotSize}`
			);
		}
	}

	// First-fit in slot creation order (R3), recording ids per slot (R4).
	const slots = []; // [freeSpace, ids]
	for (const item of ordered) {
		let placed = false;
		for (const slot of slots) {
			if (slot[0] >= item.size) {
				slot[0] -= item.size;
				slot[1].push(item.id);
				placed = true;
				break;
			}
		}
		if (!placed) {
			slots.push([slotSize - item.size, [item.id]]);
		}
	}

	return slots.map((slot) => slot[1]);
}

